import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

final class HarFormat {
    static List<Object> pairs(Map<String,List<String>> headers){List<Object> out=new ArrayList<>();headers.forEach((name,values)->values.forEach(value->out.add(Map.of("name",name,"value",value))));return out;}
    static void exportFile(VulnApp app,Path path)throws Exception{List<Object> entries=new ArrayList<>();for(var e:app.entries){if(e.method().equals("CONNECT"))continue;var p=VulnApp.parse(e.request());Map<String,List<String>> h=new LinkedHashMap<>();p.headers().forEach((k,v)->h.put(k,List.of(v)));String response=new String(e.response(),VulnApp.WIRE);int at=response.indexOf("\r\n\r\n");byte[] bytes=at<0?new byte[0]:Arrays.copyOfRange(e.response(),at+4,e.response().length);entries.add(Map.of("startedDateTime",java.time.Instant.now().toString(),"time",e.millis(),"request",Map.of("method",p.method(),"url",e.url(),"httpVersion","HTTP/1.1","headers",pairs(h),"queryString",List.of(),"cookies",List.of(),"headersSize",-1,"bodySize",p.body().length,"postData",Map.of("mimeType",p.header("Content-Type"),"text",new String(p.body(),StandardCharsets.UTF_8))),"response",Map.of("status",e.code(),"statusText",VulnApp.reason(e.code()),"httpVersion","HTTP/1.1","headers",pairs(WorkbenchCore.headers(new VulnApp.Reply(e.code(),e.response(),bytes.length))),"cookies",List.of(),"content",Map.of("size",bytes.length,"mimeType","application/octet-stream","encoding","base64","text",Base64.getEncoder().encodeToString(bytes)),"redirectURL","","headersSize",-1,"bodySize",bytes.length),"cache",Map.of(),"timings",Map.of("send",0,"wait",e.millis(),"receive",0)));}Files.writeString(path,Json.write(Map.of("log",Map.of("version","1.2","creator",Map.of("name","VULN","version","4.0"),"entries",entries))));}
    static void importFile(VulnApp app,Path path)throws Exception{if(Files.size(path)>32*1024*1024)throw new IOException("HAR maximum 32 MiB");Map<String,Object> root=Json.object(Json.parse(Files.readString(path)));Object rows=Json.object(root.get("log")).get("entries");if(!(rows instanceof List<?> list)||list.size()>10000)throw new IOException("HAR entries invalid");List<VulnApp.Exchange> imported=new ArrayList<>();for(Object row:list){Map<String,Object> e=Json.object(row),req=Json.object(e.get("request")),res=Json.object(e.get("response"));URI uri=VulnApp.Packet.checked(URI.create(req.get("url").toString()));LinkedHashMap<String,String> headers=new LinkedHashMap<>();for(Object h:(List<?>)req.get("headers")){Map<String,Object> field=Json.object(h);String name=field.get("name").toString();if(name.startsWith(":"))continue;headers.put(name,field.get("value").toString());}byte[] body=new byte[0];if(req.get("postData") instanceof Map<?,?> post)body=Objects.toString(post.get("text"),"").getBytes(StandardCharsets.UTF_8);VulnApp.Packet packet=new VulnApp.Packet(req.get("method").toString(),uri.getRawPath()+(uri.getRawQuery()==null?"":"?"+uri.getRawQuery()),"HTTP/1.1",headers,body);VulnApp.parse(VulnApp.serialize(packet));int status=((Number)res.get("status")).intValue();Map<String,Object> content=Json.object(res.get("content"));byte[] replyBody="base64".equals(content.get("encoding"))?Base64.getDecoder().decode(Objects.toString(content.get("text"),"")):Objects.toString(content.get("text"),"").getBytes(StandardCharsets.UTF_8);if(replyBody.length>VulnApp.MAX_BODY)throw new IOException("HAR body limit");ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(("HTTP/1.1 "+status+" "+VulnApp.reason(status)+"\r\n").getBytes(VulnApp.WIRE));for(Object h:(List<?>)res.get("headers")){Map<String,Object> f=Json.object(h);out.write((f.get("name")+": "+f.get("value")+"\r\n").getBytes(VulnApp.WIRE));}out.write("\r\n".getBytes(VulnApp.WIRE));out.write(replyBody);var framed=VulnApp.reframe(out.toByteArray());imported.add(new VulnApp.Exchange(0,packet.method(),uri.toString(),status,VulnApp.serialize(packet),framed.raw(),((Number)e.getOrDefault("time",0)).longValue(),"HAR import"));}javax.swing.SwingUtilities.invokeLater(()->{for(var e:imported)try{app.addExchange(VulnApp.parse(e.request()),URI.create(e.url()),new VulnApp.Reply(e.code(),e.response(),0),e.millis(),e.source());}catch(Exception ex){app.error(ex);}});}
    static String csrf(VulnApp.Packet packet,URI uri){if(!Set.of("GET","POST").contains(packet.method()))throw new IllegalArgumentException("HTML forms support GET and POST only");String type=packet.header("Content-Type");if(packet.body().length>0&&!type.startsWith("application/x-www-form-urlencoded"))throw new IllegalArgumentException("CSRF form generator supports form-urlencoded request bodies");String fields=packet.method().equals("GET")?Objects.toString(uri.getRawQuery(),""):new String(packet.body(),StandardCharsets.UTF_8);StringBuilder html=new StringBuilder("<!doctype html><meta charset='utf-8'><title>VULN request form</title><h1>Request form</h1><form method='").append(packet.method()).append("' action='").append(AdvancedTools.html(uri.toString()).replace("'","&#39;")).append("'>");for(String pair:fields.split("&")){if(pair.isEmpty())continue;String[] p=pair.split("=",2);html.append("<input type='hidden' name='").append(AdvancedTools.html(URLDecoder.decode(p[0],StandardCharsets.UTF_8)).replace("'","&#39;")).append("' value='").append(AdvancedTools.html(URLDecoder.decode(p.length>1?p[1]:"",StandardCharsets.UTF_8)).replace("'","&#39;")).append("'>");}return html.append("<button type='submit'>Send request</button></form><p>This form does not establish that a request is vulnerable to CSRF.</p>").toString();}
}
